Scripts.OnLoad:
self.Follower:SetScript("OnClick", GarrisonBuildingFollowerButton_OnClick);
self.Follower:SetScript("OnEnter", GarrisonBuildingFollowerButton_OnEnter);
self.Follower:SetScript("OnLeave", GarrisonBuildingFollowerButton_OnLeave);

self:RegisterForDrag("LeftButton");
local idle = { Play = function() end, Stop = function() end, IsPlaying = function() return false end }
if not self.BuildingGlowPulseAnim then self.BuildingGlowPulseAnim = idle end
if not self.BuildingCreateFlareAnim then self.BuildingCreateFlareAnim = idle end

self:RegisterForDrag("LeftButton");
local idle = { Play = function() end, Stop = function() end, IsPlaying = function() return false end }
if not self.BuildingGlowPulseAnim then self.BuildingGlowPulseAnim = idle end
if not self.BuildingCreateFlareAnim then self.BuildingCreateFlareAnim = idle end

Scripts.OnEnter:
if (self.tooltip) then
	GameTooltip:SetOwner(self, "ANCHOR_TOPLEFT")
	GameTooltip:SetText(self.tooltip, nil, nil, nil, nil, true);
	GameTooltip:Show();
end
